import{_ as a,o as p,a as n,b as c}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/l1_memory_bank.B9UM_M0P.png",e="/ascendc.github.io/pr/5487/assets/l0al0b_memory_bank.Crpk2Qbu.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"L1 Buffer/L0A Buffer/L0B Buffer内存结构介绍","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/L1_L0A_B_memory_structure_intro"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/L1_L0A_B_memory_structure_intro.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/L1_L0A_B_memory_structure_intro.md","outlineHeaders":[{"level":2,"title":"L1 Buffer内存结构","slug":"L1-Buffer内存结构","link":"#L1-Buffer内存结构"},{"level":2,"title":"L0A Buffer/L0B Buffer内存结构","slug":"L0A-Buffer/L0B-Buffer内存结构","link":"#L0A-Buffer/L0B-Buffer内存结构"}],"lastUpdated":1785832713000}'),t={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/L1_L0A_B_memory_structure_intro.md"};function i(r,s,_,o,B,u){return p(),n("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>L1 Buffer、L0A Buffer/L0B Buffer内存结构介绍<span id="ZH-CN_TOPIC_0000002538231122"></span></h1><p>为提升数据访问效率和吞吐量，Buffer采用了等容量的内存模块（Bank）结构设计。内存空间被划分为多个Bank，并以Bank为单位进一步分组形成多个Bank Group（BG）；每个Bank Group包含若干Bank，每个Bank都是一个可独立操作的存储单元子模块。</p><p>下面将介绍Cube侧相关内存（L1 Buffer、L0A Buffer、L0B Buffer）的详细结构。</p><h2 id="L1-Buffer内存结构">L1 Buffer内存结构<span id="zh-cn_topic_0000002545385271_section133445171205"></span><a class="header-anchor" href="#L1-Buffer内存结构">​</a></h2><p>L1 Buffer的总容量为512K字节，由16个Bank组成。每个Bank的容量为32K字节，由1024行组成，每行的宽度为32字节。<strong>同一Bank最多同时允许一读或一写</strong>。</p><p>这16个Bank被进一步组织为8个Bank Group。每个Bank Group包含2个Bank（Bank0和Bank1）。<strong>同属于一个Bank Group的两个Bank支持一个读、另一个写，但不支持同时读或同时写</strong>。</p><p>L1 Buffer的内存结构如<a href="#zh-cn_topic_0000002545385271_fig5383229131020">图1</a>所示，地址编码格式如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">L1_ADDR</span><span class="p">[</span><span class="mi">18</span><span class="o">:</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="n">BANK</span><span class="p">[</span><span class="mi">0</span><span class="o">:</span><span class="mi">0</span><span class="p">],</span><span class="w"> </span><span class="n">BANK_DEPTH</span><span class="p">[</span><span class="mi">9</span><span class="o">:</span><span class="mi">0</span><span class="p">],</span><span class="w"> </span><span class="n">BG</span><span class="p">[</span><span class="mi">2</span><span class="o">:</span><span class="mi">0</span><span class="p">],</span><span class="w"> </span><span class="n">BANK_WIDTH</span><span class="p">[</span><span class="mi">4</span><span class="o">:</span><span class="mi">0</span><span class="p">]}</span><span class="w">    </span><span class="c1">// bit位顺序为从高位到低位，共19位</span>
<span class="c1">// BANK表示地址所在Bank的编号，占用1位bit位，取值范围为[0, 1]</span>
<span class="c1">// BANK_DEPTH表示地址在Bank中的行数，占用10位bit位，取值范围为[0, 1023]</span>
<span class="c1">// BG表示地址所在Bank Group的编号，占用3位bit位，取值范围为[0, 7]</span>
<span class="c1">// BANK_WIDTH表示地址在Bank一行上的偏移量，占用5位bit位，取值范围为[0, 31]</span>
</code></pre></div><p><strong>图1</strong> L1 Buffer内存结构图<span id="zh-cn_topic_0000002545385271_fig5383229131020"></span><br><img src="`+l+`" alt title="L1内存结构图"></p><h2 id="L0A-Buffer/L0B-Buffer内存结构">L0A Buffer/L0B Buffer内存结构<span id="zh-cn_topic_0000002545385271_section6770135142516"></span><a class="header-anchor" href="#L0A-Buffer/L0B-Buffer内存结构">​</a></h2><p>L0A Buffer/L0B Buffer的总容量为64K字节，只包含1个Bank，有128行，每行的宽度为512字节。<strong>不允许同时读写同一个地址，允许LoadData同时写入和Mmad同时读取同一Bank的不同地址。</strong></p><p>L0A Buffer/L0B Buffer的内存结构如<a href="#zh-cn_topic_0000002545385271_fig2046019020496">图2</a>所示，L0A Buffer和L0B Buffer采用相同的地址编码格式：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">L0A_ADDR</span><span class="p">[</span><span class="mi">15</span><span class="o">:</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="w"> </span><span class="n">BANK_DEPTH</span><span class="p">[</span><span class="mi">6</span><span class="o">:</span><span class="mi">0</span><span class="p">],</span><span class="w"> </span><span class="n">BANK_WIDTH</span><span class="p">[</span><span class="mi">8</span><span class="o">:</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="p">}</span><span class="w">    </span><span class="c1">// bit位顺序为从高位到低位，共16位</span>
<span class="n">L0B_ADDR</span><span class="p">[</span><span class="mi">15</span><span class="o">:</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="w"> </span><span class="n">BANK_DEPTH</span><span class="p">[</span><span class="mi">6</span><span class="o">:</span><span class="mi">0</span><span class="p">],</span><span class="w"> </span><span class="n">BANK_WIDTH</span><span class="p">[</span><span class="mi">8</span><span class="o">:</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="p">}</span>
<span class="c1">// BANK_DEPTH表示地址在Bank中的行数，占用7位bit位，取值范围为[0, 127]</span>
<span class="c1">// BANK_WIDTH表示地址在Bank一行上的偏移量，占用9位bit位，取值范围为[0, 511]</span>
</code></pre></div><p><strong>图2</strong> L0A Buffer/L0B Buffer内存结构图<span id="zh-cn_topic_0000002545385271_fig2046019020496"></span><br><img src="`+e+'" alt title="L0A-B内存结构图"></p></article></div>',1)])])}const A=a(t,[["render",i]]);export{m as __pageData,A as default};
